from taf.ul.ettf.sim.simulators.egate import EgateCommand
from taf.ul.ettf.sim.core.command import Command
from taf.ul.ettf.sim.core.validators import Validators


class ThroughputCommand(EgateCommand):
    PROMPT = 'EGATE>'

    def __init__(self, command, validators=Validators(), parser=None):
        super(ThroughputCommand, self).__init__(command=command,
                                                validators=validators,
                                                parser=parser,
                                                stop_regex=self.PROMPT)
        Command.command_elements.add_modulator('retry', 2)
